export function Alignment({
  textAlign = "{{textAlign}}",
  itemsAlign = "{{itemsAlign}}",
  gap = {{gap}},
  accent = "{{accent}}",
}) {
  const chip = { width: 34, background: accent, borderRadius: 6, display: "flex", alignItems: "center", justifyContent: "center", fontWeight: 700 };
  return (
    <div style={{ font: "14px/1.5 system-ui, sans-serif", color: "#241430", width: 300 }}>
      <p style={{ margin: "0 0 14px", textAlign, background: "#FAF7F2", border: "1.5px dashed #24143055", borderRadius: 8, padding: 10, boxSizing: "border-box" }}>
        Aligned to the {textAlign} edge.
      </p>
      <div style={{ display: "flex", alignItems: itemsAlign, gap, background: "#FAF7F2", border: "1.5px dashed #24143055", borderRadius: 8, padding: 10, boxSizing: "border-box", minHeight: 60 }}>
        <span style={{ ...chip, height: 28 }}>A</span>
        <span style={{ ...chip, height: 44 }}>B</span>
        <span style={{ ...chip, height: 36 }}>C</span>
      </div>
      <p style={{ marginTop: 10, fontSize: 12, color: "#241430cc" }}>text-align: {textAlign} &middot; align-items: {itemsAlign} &middot; gap {gap}px</p>
    </div>
  );
}
